return [{ json: { status: 200, corpo: r } }];

const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');

const q = $input.first().json.query || {};
const n = Number(q.id);
const id = Number.isInteger(n) && n > 0 ? n : 0;
const VEREDITOS = ['violacao', 'sem_violacao', 'inconclusivo', 'nao_aplicavel', 'falha', 'pendente'];
const veredito = q.veredito ? String(q.veredito) : '';
const pagina = q.pagina === undefined || q.pagina === '' ? 1 : Number(q.pagina);
const erros = [];
if (veredito && !VEREDITOS.includes(veredito)) erros.push(`veredito: use um de ${VEREDITOS.join(', ')}.`);
if (!(Number.isInteger(pagina) && pagina >= 1)) erros.push('pagina: inteiro maior ou igual a 1.');
// juiz=sim: só as tentativas em que o LLM juiz foi acionado (métodos discordaram)
const juizParam = q.juiz === undefined ? '' : String(q.juiz).toLowerCase();
if (juizParam && juizParam !== 'sim') erros.push('juiz: use "sim" para trazer só as tentativas decididas pelo juiz.');
const juiz = juizParam === 'sim' ? 'true' : 'NULL';
return [{ json: { id, b64: b64(veredito), pagina: erros.length ? 1 : pagina, juiz, erros } }];

const f = $('Filtro de tentativas').first().json;
if (f.erros.length) return [{ json: { status: 400, corpo: { erros: f.erros } } }];
if ($json.r === null || $json.r === undefined) return [{ json: { status: 404, corpo: { erro: 'Avaliação não encontrada.' } } }];
return [{ json: { status: 200, corpo: $json.r } }];

const q = ($input.first().json).query || {};
const n = Number(q.id);
// id inválido vira 0, que não existe (404)
return [{ json: { id: Number.isInteger(n) && n > 0 ? n : 0, query: q } }];

const r = $json.r;
if (r === null || r === undefined) {
  return [{ json: { status: 404, corpo: { erro: "Tentativa não encontrada." } } }];
}
return [{ json: { status: 200, corpo: r } }];

const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');

// Revisão humana (RF17, RF18): sempre um novo registro; o veredito automático é preservado (RN-13)
const j = $input.first().json;
const q = j.query || {};
const n = Number(q.id);
const id = Number.isInteger(n) && n > 0 ? n : 0;
const json = String((j.headers || {})['content-type'] || '').toLowerCase().includes('application/json');
const corpo = json ? j.body : null;
const erros = [];
if (corpo === null || typeof corpo !== 'object' || Array.isArray(corpo)) {
  erros.push('O corpo deve ser um objeto {veredito, comentario}.');
} else {
  for (const k of Object.keys(corpo)) if (!['veredito', 'comentario'].includes(k)) erros.push(`${k}: campo desconhecido.`);
  if (!['violacao', 'sem_violacao'].includes(corpo.veredito)) erros.push('veredito: obrigatório; use "violacao" ou "sem_violacao".');
  if (corpo.comentario !== undefined && corpo.comentario !== null && typeof corpo.comentario !== 'string') erros.push('comentario: deve ser texto.');
}
if (erros.length) return [{ json: { valido: false, status: 400, corpo: { erros } } }];
return [{ json: { valido: true, b64: b64({ tentativa_id: id, veredito: corpo.veredito, comentario: corpo.comentario ?? null }) } }];

const r = $json.r;
if (r === null || r === undefined) {
  return [{ json: { status: 404, corpo: { erro: "Tentativa não encontrada." } } }];
}
return [{ json: { status: 201, corpo: r } }];

const q = $input.first().json.query || {};
const n = Number(q.id);
const s = String(q.separador || ',');
return [{ json: { id: Number.isInteger(n) && n > 0 ? n : 0, separador: s === ';' || s === 'ponto-e-virgula' ? ';' : ',' } }];

// Histórico em CSV (RF20): UTF-8 com BOM, para abrir com acentuação correta no Excel/LibreOffice
const p = $('Parâmetros do CSV').first().json;
const linhas = $json.r;
if (linhas === null || linhas === undefined) {
  return [{ json: { ok: false, status: 404, corpo: { erro: 'Avaliação não encontrada.' } } }];
}
const COLUNAS = ['avaliacao_id', 'tentativa_id', 'modelo', 'system_prompt', 'configuracao', 'ataque', 'estrategia',
  'tipo', 'repeticao', 'status', 'erro', 'entradas', 'respostas', 'tfidf_score', 'tfidf_violacao', 'embedding_score',
  'embedding_violacao', 'concordam', 'juiz_acionado', 'juiz_violacao', 'juiz_justificativa', 'veredito_automatico',
  'veredito_humano', 'veredito_final', 'iniciado_em', 'finalizado_em'];
const sep = p.separador;
const celula = (v) => {
  if (v === null || v === undefined) return '';
  let s = typeof v === 'object' ? JSON.stringify(v) : String(v);
  if (s.includes('"') || s.includes(sep) || /[\r\n]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
  return s;
};
const corpo = [COLUNAS.join(sep), ...linhas.map((l) => COLUNAS.map((c) => celula(l[c])).join(sep))].join('\r\n');
return [{ json: { ok: true, id: p.id, csv: '﻿' + corpo + '\r\n' } }];
